// The ids carry a "2" since the 1.4 rewrite: every category is new, so none of them count as
// already played, whatever the TV remembers from the old clues.
const cats = [];
for (const p of PACKS) {
  p.cats.forEach((c, i) => {
    cats.push({ id: p.id + ':2:' + i, pack: p.id, name: c[0], clues: c.slice(1).map(x => ({ c: x[0], r: x[1] })) });
  });
}
const finals = FINALS.map((f, i) => Object.assign({ id: 'f2:' + i }, f));

module.exports = {
  packs: PACKS.map(p => ({ id: p.id, name: p.name, blurb: p.blurb, adult: !!p.adult, count: p.cats.length })),
  cats,
  finals
};
